class.description:
Le nœud ne lit aucune entrée : on lui transmet un mouvement avec [method look_around] (souris, stick droit...). Il modifie une rotation cible du [member arm_3d] — lacet autour de Y, tangage autour de X borné entre [member min_pitch] et [member max_pitch] — que le bras rejoint en douceur ([member use_smoothing]).
Structure type : [code]Joueur › OrbitalCamera › SpringArm3D › Camera3D[/code]. Le [SpringArm3D] gère la distance et les collisions avec le décor ; l'OrbitalCamera ne gère que l'orientation.
[codeblock]
@onready var orbite: OrbitalCamera = $OrbitalCamera

func _ready() -> void:
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion:
		orbite.look_around(event.relative)

func _process(delta: float) -> void:
	var stick := Input.get_vector("cam_gauche", "cam_droite", "cam_haut", "cam_bas")
	orbite.look_around(stick * 600.0 * delta)
[/codeblock]
[b]Note :[/b] classe d'exécution uniquement : dans l'éditeur, le bras garde la rotation réglée à la main.
